INSERT INTO Projects(Name,Description,GitLink,ProjectLink, ProjectImg) 
VALUE('Blog','Ik heb deze blog in een aantal weken tijd in elkaar gezet. De Blog is gemaakt met de het javascript framework React, css, php en SQL. Je kan als je een admin van de site bent inloggen en een post toevoegen of aanpassen. Als je een post toevoegd moet je eerst kiezen uit een van de drien categorien news, books of movies. Dit is hetzelfde geval als je een post wilt aanpassen alleen dan kies je niet alleen een categorie maar ook een post. Bij het aanpassen kun je er ook voor kiezen om de post te verwijderen. 
Als bezoeker kun je deze posts bekijken. Op de homepagina kom je meteen bij nieuws. bij books zijn boeken reviews en bij movie zijn movie reviews. 
Alle post worden geladen uit een data base en worden dmv de .map() function dynamisch geladen. 
', 'https://github.com/Jessica-vdz/blog','https://jessuccblog.com/home', 'blog');

INSERT INTO Projects(Name,Description,GitLink,ProjectLink,ProjectVideo, ProjectImg) 
VALUE ('Better Home', 'Better Home is een project waarbij we in een team van 3 personen hebben gewerkt aan een smart home maken. Dit was mijn eerste project waarbij ik werkte met arduino en php. Ons huisje praatte met onze website waar wij de lampjes aan en uit konden zetten. Ook hadden wij zonnepanelen en een eigen gemaakt zonnescherm. deze werd aangedreven door een servo die wachtte op de input van de ldr die net boven het zonnescherm zat.', 'https://github.com/Jessica-vdz/BetterHome/', 'https://39300.hosts2.ma-cloud.nl/BetterHome/', 'https://www.youtube.com/watch?is=0bfoYO0Jpc9L5oQe&v=W3MwVEPC1I8&feature=youtu.be','betterhome');

INSERT INTO Projects(Name, Description,GitLink, ProjectImg) 
VALUE('Burning Voices', 'Dit project heb ik gemaakt voor mijn keuzedeel  Special Input Output waarbij het de bedoeling was om een apparaat te maken waar muziek uit kwam. Burning Voices is een jukebox met een disc die twee kleuren bevat. In de "jukebox" zit een ldr sensor en een led. Als je de disc in de box stopt weerkaatst het licht van de disc af wat de ldr sensor weer opvangt. Doordat de disc verschillende kleuren heeft kijgt hij dus ook verschillende waardes. Elke kleur van de disc heeft zijn eigen mapje met liedjes die de doos dan afspeelt dmv een dfplayer en speaker die ook in de doos zitten. Ik heb er ook een website bij gemaakt die op basis van de muziek data laad op de website. Ik heb dit project gemaakt met HTML, CSS, JavaScript en C ( Arduino ) ', 'https://github.com/Jessica-vdz/TechSpeeltuin-ToasterBox', 'bv' );
